const input=$input.first().json;
try {
  const base=$env.INSULA_CRM_BASE_URL, apiKey=$env.INSULA_CRM_API_KEY;
  const leadId=Number(input.insulaLeadId||input.leadId||input.lead_id||input.offer?.lead_id||0);
  const lifecycle=input.offer_lifecycle||{};
  if(base&&apiKey&&leadId){
    await this.helpers.httpRequest({
      method:'POST', url:base+'/api/v1/activities',
      headers:{'X-API-Key':apiKey,'Content-Type':'application/json',
        'Idempotency-Key':'acquisition:offer-decision:'+leadId+':'+String(input.offer_id||lifecycle.offer_id||'offer')+':'+String(lifecycle.status||'unknown')+':v1'},
      body:{lead_id:leadId,type:'stage_change',
        subject:'Seller offer decision: '+String(lifecycle.status||'unknown'),
        body:'Offer lifecycle decision recorded. Previous status: '+String(lifecycle.previous_status||'none')+'. Current status: '+String(lifecycle.status||'unknown')+'. CRM stage: '+String(lifecycle.crm_stage||'offer_review_needed')+'. Next action: '+String(lifecycle.next_action||'review_required')+'. Transition valid: '+String(lifecycle.transition_valid===true)+'.'},
      json:true
    });
  }
}catch(error){ console.log('InsulaCRM seller offer decision activity sync failed:',error.message); }
return [{json:input}];
